<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import PageHeader from '@/components/common/PageHeader.vue';
import { templatesApi } from '@/api/coreFeatures';
import type { AudienceTemplate, PaperTemplate } from '@/types';
const tab=ref('paper'); const papers=ref<PaperTemplate[]>([]); const audiences=ref<AudienceTemplate[]>([]); const dialog=ref(false); const kind=ref<'paper'|'audience'>('paper'); const editId=ref('');
const form=reactive({name:'',description:'',json:'{}'});
async function load(){[papers.value,audiences.value]=await Promise.all([templatesApi.papers(),templatesApi.audiences()]);}
function open(k:'paper'|'audience',item?:PaperTemplate|AudienceTemplate){kind.value=k;editId.value=item?.id??'';form.name=item?.name??'';form.description=item?.description??'';form.json=JSON.stringify(item ? ('config' in item?item.config:item.rules) : (k==='paper'?{}:{departmentIds:[],groupIds:[],positionIds:[],includeUserIds:[],excludeUserIds:[],includeSubDepartments:true,randomCount:null}),null,2);dialog.value=true;}
function openPaper(row: unknown){ open('paper', row as PaperTemplate); }
function openAudience(row: unknown){ open('audience', row as AudienceTemplate); }
async function save(){let data:Record<string,unknown>;try{data=JSON.parse(form.json)}catch{return ElMessage.error('参数 JSON 格式不正确')}if(kind.value==='paper')await templatesApi.savePaper({name:form.name,description:form.description,config:data},editId.value||undefined);else await templatesApi.saveAudience({name:form.name,description:form.description,rules:data as never},editId.value||undefined);dialog.value=false;ElMessage.success('已保存');await load();}
async function remove(k:'paper'|'audience',id:string){await ElMessageBox.confirm('确认删除模板？','删除',{type:'warning'});k==='paper'?await templatesApi.removePaper(id):await templatesApi.removeAudience(id);await load();}
onMounted(load);
</script>
<template><div class="page"><PageHeader title="模板管理" description="组卷参数模板与人员抽考模板只影响应用时刻，已创建考试的冻结名单不会随模板变化"/><el-card shadow="never"><el-tabs v-model="tab"><el-tab-pane label="组卷参数模板" name="paper"><div class="actions"><el-button type="primary" @click="open('paper')">新增模板</el-button></div><el-table :data="papers"><el-table-column prop="name" label="模板名称"/><el-table-column prop="description" label="说明"/><el-table-column prop="updatedAt" label="更新时间" width="190"/><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="primary" @click="openPaper(row)">编辑</el-button><el-button link type="danger" @click="remove('paper',row.id)">删除</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="人员抽考模板" name="audience"><div class="actions"><el-button type="primary" @click="open('audience')">新增模板</el-button></div><el-table :data="audiences"><el-table-column prop="name" label="模板名称"/><el-table-column prop="description" label="说明"/><el-table-column label="随机人数" width="110"><template #default="{row}">{{ row.rules.randomCount ?? '全部' }}</template></el-table-column><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="primary" @click="openAudience(row)">编辑</el-button><el-button link type="danger" @click="remove('audience',row.id)">删除</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></el-card><el-dialog v-model="dialog" :title="editId?'编辑模板':'新增模板'" width="640"><el-form label-width="90"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description"/></el-form-item><el-form-item label="参数 JSON"><el-input v-model="form.json" type="textarea" :rows="14"/><div class="hint">组卷参数可保存题库范围、题型题量、分值、目标难度与乱序；抽考参数支持 departmentIds、groupIds、positionIds、includeUserIds、excludeUserIds、includeSubDepartments、randomCount。</div></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<style scoped>.page{display:flex;flex-direction:column;gap:16px}.actions{display:flex;justify-content:flex-end;margin-bottom:12px}.hint{font-size:12px;color:var(--el-text-color-secondary);line-height:1.6}</style>
